    "price_display": "€2.500.000",
    "rooms": 5,
    "bedrooms": 4,
    "bathrooms": 3,
    "surface_sqm": 842,
    "surface_sqft": 9063,
    "description": "CAPITOL, CONSTANȚA | O PROPRIETATE CU DUBLĂ IDENTITATE\n\nRezidență premium. Arhitectură istorică. Potențial comercial, în inima orașului.\n\nSituată în zona Capitol, la intersecția dintre Strada Ion Bănescu și Bulevardul Tomis, această proprietate distinctivă îmbină confortul unei reședințe premium cu oportunitatea valorificării unei clădiri istorice separate.\n\nPROPRIETATEA\n\n— Teren de aproximativ 842 mp, cu dublă deschidere\n— Vilă renovată premium, cu o suprafață construită estimată la aproximativ 400 mp\n— 4 dormitoare\n— 5 camere cu băi proprii\n— Living generos și terasă\n— Tâmplărie QFort\n— Curte amenajată, cu drenaj realizat, pregătire pentru sistem de irigații și zonă de relaxare\n\nO A DOUA OPORTUNITATE\n\nÎn completarea vilei, proprietatea include o clădire istorică independentă, cu potențial pentru dezvoltarea unui concept comercial sau reprezentativ: restaurant, cafenea, boutique hotel, galerie de artă ori sediu de companie.\n\nDubla deschidere și poziționarea centrală oferă flexibilitate în utilizarea proprietății, atât în scop rezidențial, cât și comercial, în funcție de reglementările și autorizațiile aplicabile.\n\nO adresă. Două clădiri. Multiple posibilități de valorificare.\n\n📍 Zona Capitol — Str. Ion Bănescu / Bd. Tomis, Constanța\n\nPREȚ: 2.500.000 EUR\n\n🌐 HomeFind.CristianVaduva.com",
