    "description": "Ansamblul rezidential de case\n\nLocalizare: Ansamblul de case in Pipera, ofera locuinte intr-o zona linistita si accesibila, ideala pentru familii.\nPretul caselor porneste de la 400.000 EUR + TVA pentru varianta semifinisata, cu optiunea de predare finisata complet, la cerere.\n\nDetalii despre locuinte:\n\nSuprafata utila: 144 mp\nCompartimentare moderna: living cu bucatarie open-space, 3 dormitoare, birou, dressing si 3 bai\nGradina proprie: aproximativ 100 mp in spatele fiecarei case\nDoua locuri de parcare incluse\nStrada privata, acces cu bariera pentru siguranta si intimitate\nDotari si finisaje premium:\n\nTamplarie de aluminiu\nFatada ventilata si panouri fotovoltaice pentru eficienta energetica\nIncalzire in pardoseala cu centrala proprie\nPuncte de interes din proximitate:\n\nScoli internationale: Scoala Americana, Scoala Britanica, Scoala Cambridge\nMall Promenada\nSala de sport Worldclass\nAcces rapid catre centrul financiar al Bucurestiului\n\nPentru mai multe detalii sau pentru programarea unei vizionari, nu ezitati sa ne contactati!\n\nHome Find - Cristian Vaduva",
