    "surface_sqm": 106,
    "surface_sqft": 1141,
    "description": "Vila Moderna de Vanzare in Pipera Erou Iancu Nicolae\n\nDescopera o vila moderna de tip 2, intr-o zona rezidentiala in plina dezvoltare, cu acces rapid catre principale artere de circulatie, dar totodata retrasa de la agitatia urbana.\n\nAceasta proprietate exclusivista imbina functionalitatea, calitatea constructiei si designul modern, fiind alegerea ideala pentru familii care cauta atat confort, cat si o investitie sigura pe termen lung.\n\nDetalii Proprietate\n • Suprafata construita: 173 mp\n • Suprafata utila: 100 mp\n • Teren: 77 mp\n • Gradina privata: 27 mp\n • Compartimentare: 4 camere, 2+ bai, dressing, living generos\n • Finalizare: An 2025 – predare la cheie\n\nCompartimentare Moderna\n\nParter:\n• Bucatarie open space moderna\n• Living cu zona de dining si acces direct in gradina\n• Grup sanitar si spatiu de depozitare\n\nEtaj 1:\n• 2 dormitoare luminoase\n• Baie de peste 4 mp\n\nEtaj 2:\n• Dormitor matrimonial cu dressing\n• Baie proprie\n• Terasa de 9 mp – locul perfect pentru relaxare\n\nCalitate si Constructie Solida\n\nProiectul este realizat din beton armat, cadre metalice si zidarie de rezistenta, cu finisaje premium si materiale durabile:\n • Izolatie termica eficienta\n • Tamplarie cu bariera termica\n • Aer conditionat si centrala termica proprie\n • Finisaje moderne si spatii optimizate pentru confort\n\nBeneficii & Facilitati\n • Gradina privata – spatiu de relaxare pentru familie\n • Locuri de parcare disponibile\n • Zona rezidentiala linistita si civilizata\n • Predare la cheie – mutare imediata dupa finalizare\n\nPretul nu include TVA.\n\nAceasta vila moderna este alegerea perfecta pentru cei care cauta un echilibru intre viata de familie, investitie imobiliara sigura si un stil de viata premium intr-o zona exclusivista.",
