    "surface_sqm": 55,
    "surface_sqft": 592,
    "description": "Nautical Living Experience – Libertatea de a trăi pe apă\n\n⚓ Ambarcațiune premium de locuit, complet echipată, proiectată și construită după principii navale moderne, pentru confort, autonomie și mobilitate reală.\n\nIdeală pentru:\n• porturi turistice și marine\n• lacuri, râuri și fluvii\n• retreat-uri premium și turism\n• locuință de vacanță sau investiție\n\nStructură navală zincată + flotoare premium din polietilenă specială cu EPS, rezistente la șocuri, UV, umezeală și temperaturi extreme.\n\nIzolație premium termică și fonică, materiale speciale pentru mediu marin:\n✔ răcoare vara\n✔ căldură iarna\n✔ rezistență excelentă la umezeală și soare\n\nFinisaje premium și hidroizolații profesionale pentru exterior, terasă și punte panoramică.\n\nSistem electric inteligent:\n• 220V + 12V\n• acumulatori pentru autonomie\n• invertor + alternator pentru încărcare în mers\n• posibilitate panouri fotovoltaice\n• sistem alarmare și supraveghere\n• detecție fum și centrală de siguranță\n\nEchipare completă pentru autonomie pe apă:\n• rezervor apă 400 L\n• rezervor ape uzate 400 L\n• spații de depozitare integrate în flotoarele de pupă\n• scară acces apă\n• ancoră inclusă\n\nPropulsie:\nmotor termic (opțional electric), cu post de comandă complet.\n\n Model disponibil:\n• Lungime: 11 m\n• Lățime: 3,7 m\n• peste 50 mp utili cu terasa superioară\n• capacitate recomandată: 2–6 persoane\n\nComplet echipată:\n✔ dormitor matrimonial\n✔ living\n✔ bucătărie utilată\n✔ baie completă\n✔ dining\n✔ terasă + punte panoramică\n\n💶 Preț promoțional:\n74.000 € + TVA\n\nPosibilitate execuție și pe comandă, în alte dimensiuni și configurații personalizate.",
