    "surface_sqm": 372,
    "surface_sqft": 4004,
    "description": "Situat la ultimul etaj al unui imobil modern finalizat în 2014, acest penthouse oferă o combinație rar întâlnită între suprafețe generoase, intimitate și una dintre cele mai impresionante terase disponibile în această zonă.\n\nCu 114 mp utili, completați de o terasă panoramică de 220 mp și un balcon de 12 mp, proprietatea depășește conceptul unei locuințe obișnuite și oferă un stil de viață pe care puține apartamente îl pot susține.\n\nCaracteristici\n• Suprafață utilă: 114,13 mp\n• Terasă panoramică: 220 mp\n• Balcon: 12 mp\n• Suprafață construită: 372 mp\n• Etaj: 5/5\n• An construcție: 2014\n• Compartimentare decomandată\n\nCompartimentare\n• Living generos, ideal pentru relaxare și socializare\n• 3 dormitoare luminoase\n• 2 băi\n• Bucătărie separată\n• Terasa spectaculoasă\n\nFiecare încăpere beneficiază de lumină naturală, iar terasa transformă această proprietate într-un spațiu unic pentru cine private, petreceri, jacuzzi, zonă lounge sau grădină urbană.\n\nDotări\n• Centrală termică proprie\n• Aer condiționat\n• Structură din beton\n• Finisaje moderne\n• Imobil cu regim redus de înălțime\n\nDe ce această proprietate?\n✔ Terasă de 220 mp, o suprafață rar întâlnită în centrul Bucureștiului\n✔ Ultimul etaj, cu intimitate și vedere panoramică\n✔ Compartimentare eficientă pentru familie sau entertaining\n✔ Potrivită atât pentru locuire, cât și pentru investiție premium\n✔ Posibilitatea amenajării unui adevărat rooftop privat\n\nLocalizare\nPoziționat pe Calea Plevnei, apartamentul beneficiază de acces rapid către:\n• Piața Victoriei\n• Gara de Nord\n• Centrul Bucureștiului\n• Cotroceni\n• Universități\n• Clădiri de birouri\n• Restaurante și centre comerciale\n\nO locație care oferă mobilitate excelentă și acces rapid către principalele puncte de interes ale orașului.\n\n📩 Contact\nhttps://linktr.ee/cristianvaduvarealestate\n🌐 cristianvaduva.com | AiXLuxury.com\nReal Estate | Insurance | Investments \nHome Find - AiX OS",
