    "surface_sqm": 352,
    "surface_sqft": 3789,
    "description": "Apartament cu 5 Camere | 352,5 mp Total | Terase Spectaculoase | Up-Site Floreasca\n\nSituat in cadrul ansamblului rezidential Up-Site Floreasca, unul dintre cele mai exclusiviste proiecte din Bucuresti, acest apartament impresioneaza prin dimensiuni rare, compartimentare inteligenta, terase generoase si o locatie aflata in centrul celei mai dinamice zone premium din Capitala.\n\nCu o suprafata totala de 352,5 mp, locuinta este conceputa pentru cei care apreciaza spatiul, lumina naturala si confortul unui stil de viata contemporan.\n2 locuri de parcare subterane si 2 boxe sunt incluse in pret.\nCompartimentare\n• Zona de living si dining de peste 109 mp, ideala pentru relaxare sau socializare\n• Dormitor matrimonial cu dressing si baie proprie\n• 3 dormitoare suplimentare, perfecte pentru familie, birou sau camere de oaspeti\n• 4 bai complet echipate\n• Multiple spatii de depozitare\n• Terase generoase cu vedere panoramica si potential excelent de amenajare\n\nFerestrele ample permit luminii naturale sa patrunda pe tot parcursul zilei, oferind o atmosfera deschisa si echilibrata.\nFinisaje & Tehnologie\nApartamentul se preda complet finisat.\n• Parchet multistratificat\n• Gresie si faianta premium\n• Obiecte sanitare de top\n• Usi interioare premium\n• Incalzire prin pardoseala\n• Sistem performant de climatizare\n• Tamplarie cu performante ridicate de izolare termica si fonica\n• Sistem Smart Home cu control al principalelor functii direct de pe telefon\nUp-Site Floreasca\nUn proiect rezidential de referinta, construit la cele mai inalte standarde, ce ofera un stil de viata complet.\nFacilitati:\n• Piscina\n• Sala de fitness\n• Parc privat amenajat\n• Receptie\n• Paza permanenta\n• Supraveghere video 24/7\n• Lifturi de mare viteza\n• Parcari subterane\n• Clasa energetica A\n• Infrastructura completa pentru internet de mare viteza\nLocalizare\nPozitionat in zona Floreasca – Aviatiei, una dintre cele mai cautate destinatii rezidentiale din Bucuresti.\n\nContact:\n🔗 https://linktr.ee/cristianvaduvarealestate\n🌐 cristianvaduva.com | AiXLuxury.com\nReal Estate | Insurance | Investments",
