    "surface_sqm": 280,
    "surface_sqft": 3014,
    "description": "Vila exclusivistă de vânzare în Pipera – Erou Iancu Nicolae\n\nO oportunitate rară într-una dintre cele mai căutate zone din nordul Bucureștiului!\nVila spațioasă cu 6 camere, 280 mp utili pe un teren generos de 500 mp, construită în 2004 și perfect întreținută.\n\nCe oferă:\n•  Living generos de ~40 mp cu acces direct spre terasă de 32 mp și grădină\n•  5 dormitoare (3 la etaj + 2 la mansardă – ideale pentru birou sau spațiu extra)\n•  3 băi (una foarte spațioasă, cu potențial de transformare)\n•  Bucătărie cu zonă de dining\n•  Panouri fotovoltaice 7 kW, centrală termică proprie + stație de dedurizare apă\n•  Curte amenajată cu zonă pavată și spațiu verde\n\nAmplasare excelentă, aproape de Iancu Nicolae, școli internaționale, mall-uri și birouri. Ideală pentru o familie care caută confort, intimitate și calitate superioara.",
