    "description": "Vila construita in anul 2010 cu acces rapid catre cartier Baneasa si Aviatiei.\n\nAmprenta casei este de 102mp la care se adauga al doilea corp de 60 de mp utili amenajat pentru spatiu comercial cu intrare separata, din strada, care în prezent produce un venit de €1050/luna, practic, achiziția casei va aduce un venit sigur, suplimentar de €12.600 anual si garajul de 30 de mp.\n\nDetalii Vila\n • Suprafata utila: 260 mp\n • Teren: 400 mp\n • Compartimentare inteligenta si eleganta:\n• Parter – living generos, birou, bucatarie cu zona de dining\n• Etaj – 3 dormitoare spatioase si luminoase\n• Mansarda – open space tip apartament cu 1dormitor (living + spatiu de dormit + baie proprie)\n\n• Acoperis tigla Tondach\n\n• Usi din sticla si termopan\n\nProprietati Aditionale\n • Cladire independenta de birouri (60 mp), inchiriata unei clinici de psihoterapie – investitie cu randament imediat.\n\n• Acoperis tigla metalica tip lindab.\n • Garaj de 30 mp cu acces direct din strada.\n\nAvantaje si Vecinatati\n • Localizare: aproape de Parcul Herastrau, Mall Promenada, centrele de afaceri din nordul capitalei, dar si de aeroport.\n • In proximitate: scoli si gradinite de top, restaurante exclusiviste, cafenele moderne si centre wellness.",
