    "id": "ro-prop-c99be4a1",
    "slug": "apartament-cu-3-camere-de-tip-loft-de-vanzare-in-floreasca-c99be4a1",
    "title": "Apartament cu 3 camere de tip Loft de vanzare in Floreasca",
    "city": "București",
    "county": "București",
    "address": "Floreasca",
    "property_type": "Apartment",
    "listing_type": "Sale",
    "price_eur": 750000,
