    "price_display": "€750.000",
    "rooms": 3,
    "bedrooms": 2,
    "bathrooms": 1,
    "surface_sqm": 230,
    "surface_sqft": 2476,
    "description": "Apartament cu 3 camere de tip Loft de vanzare in Floreasca\n\nÎn una dintre cele mai exclusiviste și apreciate zone din București, această proprietate reprezintă o oportunitate rară pentru cei care caută un apartament cu personalitate, arhitectură spectaculoasă și un potențial investițional excelent.\n\nInspirat de marile proiecte loft din metropolele internaționale, apartamentul impresionează prin volum, lumină naturală și un design contemporan care îl diferențiază complet de ofertele clasice din piață.\n\nAcesta nu este un apartament obișnuit, ci un spațiu creat pentru cei care apreciază designul și proporțiile spectaculoase.\n\nTavanele și suprafețele vitrate ating aproximativ 6 metri înălțime, oferind o senzație unică de spațiu, lumină și libertate.\n\nFațadele complet vitrate transformă fiecare încăpere într-un decor impresionant, iar terasa cu înălțime dublă completează experiența unei locuințe cu adevărat speciale.\n\nPuncte forte\nFerestre tip perete cortină pe două niveluri\nÎnălțime spectaculoasă de aproximativ 6 metri\nArhitectură loft cu influențe industriale\nTerasă generoasă cu design impresionant\nSpații ample și luminoase\nFinisaje premium\nConcept rezidențial boutique\nLocalizare premium\n\nSituat în Floreasca, una dintre cele mai valoroase zone rezidențiale din București, apartamentul oferă acces rapid către restaurante premium, cafenele, parcuri, centre de business și principalele puncte de interes din nordul Capitalei.\n\nFie că este achiziționat pentru locuire sau investiție, această proprietate reprezintă un activ rar, într-o piață în care locuințele cu o astfel de arhitectură sunt extrem de puține.\n\nUn apartament care nu impresionează doar prin suprafață, ci prin experiența pe care o oferă. Un spațiu unde arhitectura, lumina și designul creează un stil de viață aparte.",
