    "description": "Apartament situat intr-un imobil modern, cu acces facil din Sos. Fabrica de Glucoza catre zonele Barbu Vacarescu, Calea Floreasca, Cartier Aviatiei si Lacul Tei.\n\nApartamentul are o compartimentare semidecomandata si este amplasat la etajul 3 al unui imobil cu 10 niveluri. Suprafata utila este de 36.1 mp, suprafata utila totala de 47.2 mp, iar suprafata construita este de 54 mp.\n\nConfiguratia apartamentului cuprinde 2 camere (1 dormitor), 1 baie, 1 bucatarie si un balcon generos de 11 mp.\n\nImobilul este nou, finalizat in anul 2025.\n\nDotari si finisaje:\n\nCentrala termica proprie\nIncalzire in pardoseala\nGresie, faianta, parchet\nStare interior: nou\nUtilitati: curent, gaz, apa, canalizare.\n\nApartamentul se vinde nemobilat, oferindu-le viitorilor proprietari libertatea de a-l amenaja dupa propriul stil si preferinte.\n\nPretul de vanzare al apartamentului este de 169.000 Euro + TVA.\nPretul de vanzare al locului de parcare subteran este 15.000 Euro.",
