    "bedrooms": 4,
    "bathrooms": 3,
    "surface_sqm": 230,
    "surface_sqft": 2476,
    "description": "PENTHOUSE APARTHOTEL | DOROBANȚI – FLOREASCA\n\nUn penthouse exclusivist într-una dintre cele mai puternice zone ale Bucureștiului, conceput nu doar ca proprietate rezidențială, ci ca activ investițional deja operațional.\nSituat în zona Dorobanți – Floreasca, proprietatea se desfășoară pe două niveluri și oferă 230 mp utili, cu lift cu acces direct în apartament și două balcoane generoase cu vedere panoramică.\n\nCONFIGURAȚIE\n• 5 camere\n • 3 camere duble complet echipate\n • 2 apartamente independente\n • 2 balcoane generoase\n • Duplex pe etajele 5 și 6\n • Mobilat și utilat complet\n • Lift cu acces direct în apartament\n\nBUSINESS OPERAȚIONAL\nProprietatea funcționează în prezent ca aparthotel, cu activitate deja stabilizată și infrastructura necesară pentru continuarea exploatării imediat după achiziție.\n• Rată de ocupare constantă de peste 80%\n • Recenzii excelente pe platformele de închiriere\n • Business funcțional\n • Venit generat imediat\n • Fără necesitatea unei renovări sau perioade de amenajare\n\nPERFORMANȚĂ INVESTIȚIONALĂ\nRandament net estimat: 8–10% / an, în funcție de exploatare.\nPentru un investitor, avantajul major este combinația dintre proprietatea premium și cash-flow-ul deja existent.\nNu este nevoie să pornești de la zero. Achiziționezi un activ imobiliar premium împreună cu un concept de exploatare deja funcțional.\n\nUN ALT AVANTAJ IMPORTANT:\nTranzacție scutită de TVA, oferind un avantaj fiscal relevant pentru cumpărător.\n\nDOROBANȚI – FLOREASCA\nUna dintre cele mai consolidate zone premium din București, cu acces rapid către:\n• Parcul Floreasca\n • Promenada Mall\n • Piața Dorobanți\n • restaurante și cafenele premium\n • clinici și centre medicale\n • centre de business\n • principalele zone corporate ale Capitalei\nPoziționarea este potrivită pentru închiriere short & medium-term, clienți corporate, turism medical sau rezidență premium.\n\nFLEXIBILITATEA ACTIVULUI\nPoate continua ca aparthotel și genera venituri sau poate fi transformat într-o reședință privată de lux de 230 mp, în funcție de strategia noului proprietar.\n\n€785.000 | Tranzacție scutită de TVA\n 230 mp utili | Duplex | Etajele 5–6 | Business operațional\n\nO proprietate rară care combină locația, suprafața, produsul premium și un business deja operațional.\n\nDetalii complete și acces la proprietate, la cerere.",
