    "surface_sqft": 2583,
    "description": "Vila 7 camere cu suprafata utila de aprox. 240 mp, este amplasata intr-o zona verde si extrem de linistita a cartierului Floreasca\n\nZona este recunoscuta pentru accesibilitate excelenta, proximitate fata de cladiri de birouri, restaurante, centre comerciale, mijloace de transport in comun, fiind o alegere excelenta pentru activitati profesionale,\n\nVila este structurata pe Subsol, Parter si 2 nivele,\n\nSubsolul cu 2 camere una de aprozimativ 15 mp si una de 5mp, putand fi incalzite, spatiu ce se poate utiliza pentru depozitare sau arhivare, birou administrativ.\n\nParterul este compus din hol de acces generos ce poate fi folosit ca receptie sau zona asteptare, living mare, bucatarie si un grup sanitar . Tot la parter avem accesul catre curtea din spate ce beneficiaza de terasa si spatiu verde in suprafata de aproximativ 50 mp.\n\nEtajul 1 este compus din 3 camere dintre care 2 cu balcon si doua grupuri sanitare.\n\nMansarda cu 3 camere un grup sanitar si o chicineta\n\nIncalzirea se face prin centrala termica proprie, iar ca dotari mai putem enumera aerul conditionat, finisajele moderne, usa metalica, ferestre velux la mansarda si pe casa scarii, rulouri exterioare la toate geamurile, grupuri sanitare pe fiecare nivel. Vila beneficiaza de 2 locuri de parcare in fata imobilului\n\nVila se inchiriaza nemobilata\n\nDestinatii pretabile:\n\nDatorita pozitie excelente si compartimentarii total decomandate a celor 7 camere proprietate este ideala atat pentru sediu firma, cabinet notarial, birouri consultanta etc., cat si pentru resedinta",
