    "surface_sqm": 100,
    "surface_sqft": 1076,
    "description": "Apartament premium de inchiriat | The Ivy Baneasa | 100,6 mp total | Parcare subterana inclusa\n\nUnele apartamente ofera doar spatiu. Acesta ofera un stil de viata.\n\nSituat in ansamblul rezidential The Ivy Baneasa, unul dintre cele mai apreciate proiecte premium dezvoltate de Speedwell in nordul Bucurestiului, acest apartament cu 3 camere combina confortul contemporan, lumina naturala si accesul la facilitati de nivel superior. Complexul este amplasat pe Str. Jandarmeriei 9A si beneficiaza de piscina, sala de fitness, restaurant, magazin, spatii verzi ample si acces rapid catre zona de business, Baneasa Shopping City si Aeroportul Henri Coanda. [turn0search0][turn0search1]\n\n📐 Suprafata & Compartimentare\n• Suprafata interioara: 81,9 mp\n• Terase: 18,7 mp\n• Suprafata totala: 100,6 mp\n• Etaj: 4 din 6\n• 1 loc de parcare subteran inclus\n\n🛋️ Configuratie\n• Living & dining generos – 25,6 mp\n• Bucatarie separata – 5,7 mp\n• Dormitor matrimonial – 15,3 mp\n• Dormitor secundar – 12,0 mp\n• 2 bai\n• Hol si spatii de depozitare\n• Doua terase ideale pentru cafeaua de dimineata sau relaxare seara\n\n✨ De ce The Ivy?\n✔ Complex premium cu arhitectura moderna si multe spatii verzi\n✔ Piscina, fitness, restaurant si magazin in cadrul ansamblului\n✔ Acces rapid catre DN1, Aeroport si zona de business din nord\n✔ Aproape de Baneasa Shopping City, Stejarii Country Club si scoli internationale\n✔ Comunitate selecta si atmosfera linistita\n\n💶 Chirie: 1.450 €/luna\n🚗 1 loc de parcare subteran inclus\n\n📩 Pentru detalii si vizionare privata:\nhttps://linktr.ee/cristianvaduvarealestate\n\n🌐 cristianvaduva.com | AiXLuxury.com\n\nReal Estate | Insurance | Investments",
