    "slug": "apartament-2-camere-luminos-si-modern-de-inchiriat-in-nusco--d69152fe",
    "title": "Apartament 2 camere luminos si modern de inchiriat in Nusco City – Pipera",
    "city": "București",
    "county": "București",
    "address": "Pipera",
    "property_type": "Apartment",
