    "bathrooms": 1,
    "surface_sqm": 66,
    "surface_sqft": 710,
    "description": "Apartament 2 camere luminos si modern de inchiriat in Nusco City – Pipera\n\nApartament modern si primitor situat la etajul 3 in complexul Nusco City, zona Pipera, una dintre cele mai cautate zone din nordul Bucurestiului.\nApartamentul are o suprafata utila de 55,4 mp + un balcon de 10,7 mp, fiind perfect compartimentat si foarte luminos.\n\nLiving spatios si bucatarie inchisa. Dormitorul ofera intimitate si confort. Totul este bine gandit, cu finisaje moderne si o senzatie de aer si spatiu.\n\nDe ce iti va placea aici:\n• Locatie excelenta in Nusco City, cu tot ce ai nevoie la doi pasi\n• Zona verde, linistita si bine conectata\n• La doar cateva minute de metrou (Pipera & Aurel Vlaicu), Promenada Mall, restaurante si birouri\n• Complex cu securitate permanenta si facilitati moderne\n\nEste ideal pentru un cuplu tanar, un profesionist sau un expat care cauta un camin confortabil, modern si usor de intretinut, intr-o zona vibranta si sigura.\n\nDaca iti place sa locuiesti intr-un complex nou, unde ai si liniste si tot confortul urban, acesta este apartamentul potrivit.",
