export function getRomaniaPropertyById(id: string): RomaniaPropertyRecord | undefined {
  return ROMANIA_PROPERTIES.find((p) => p.id === id || p.slug === id)
}

export function getRomaniaPropertyBySlug(slug: string): RomaniaPropertyRecord | undefined {
  return ROMANIA_PROPERTIES.find((p) => p.slug === slug)
}
